import {activity,businesses,categories,cravings,newcomers,promotions,sideAds,teamTops,weeklyPoll,eventCategories,mockEvents,type RadarEvent,type EventMode,type Business,type Promotion,type PromoPeriod} from "@/lib/radar-data";
