// Los negocios ficticios de ejemplo no tienen ubicación real, así que no se buscan en el mapa.
const mappable=businesses.filter(b=>!b.fictional);
function mapsQuery(b:Business){return `${b.name}, Chihuahua, México`}
function mapsUrl(b:Business){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(mapsQuery(b))}`}
function straightLineKm(a:MapPoint,b:MapPoint){const radians=Math.PI/180;const dLat=(b.lat-a.lat)*radians,dLng=(b.lng-a.lng)*radians;const h=Math.sin(dLat/2)**2+Math.cos(a.lat*radians)*Math.cos(b.lat*radians)*Math.sin(dLng/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function distanceLabel(km:number){return km<1?`${Math.round(km*1000)} m`:`${km.toFixed(1)} km`}
const nav:{href:string;label:string;color?:string}[]=[{href:"/explorar",label:"Explorar"},{href:"/promociones",label:"Promociones"},{href:"/eventos",label:"Eventos",color:"#9563a9"},{href:"/mapa",label:"Mapa"},{href:"/para-negocios",label:"Para negocios"}];
function go(r:any,p:string){r.push(p);window.scrollTo({top:0,behavior:"smooth"})}
function Logo({compact=false,size}:{compact?:boolean;size?:number}){const px=size??(compact?42:54);return <a className="brand" href="/"><Image className="brand-full" src="/brand/radarlocal-logo.png" width={px} height={px} alt="RadarLocal" priority/><Image className="brand-icon" src="/brand/radarlocal-icon.png" width={40} height={40} alt="" aria-hidden="true"/><span><b>Radar</b><strong>Local</strong></span></a>}

export default function RadarApp(){const router=useRouter(),path=usePathname();const[favs,setFavs]=useState<string[]>([]),[role,setRole]=useState(""),[demo,setDemo]=useState(false);useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem("rl-favorites")||"[]");setFavs(Array.isArray(saved)?saved.filter((id):id is string=>typeof id==="string"):[])}catch{setFavs([])}setRole(localStorage.getItem("rl-role")||"")},[]);const fav=(id:string)=>{const n=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];setFavs(n);localStorage.setItem("rl-favorites",JSON.stringify(n))};const login=(r:string)=>{localStorage.setItem("rl-role",r);setRole(r);setDemo(false);go(router,r==="owner"?"/panel-negocio":"/mi-cuenta")};const reset=()=>{["rl-role","rl-favorites","rl-promos","rl-promo-period","rl-profile","rl-filters","rl-events"].forEach(x=>localStorage.removeItem(x));setFavs([]);setRole("");setDemo(false);go(router,"/")};let page=<Home router={router} favs={favs} fav={fav}/>;if(path==="/explorar"||path.startsWith("/categorias/"))page=<Explore router={router} initial={path.split("/")[2]||""} favs={favs} fav={fav}/>;else if(path.startsWith("/negocio/"))page=<Profile slug={path.split("/")[2]} favs={favs} fav={fav}/>;else if(path==="/promociones")page=<Promotions/>;else if(path==="/eventos")page=<Events/>;else if(path==="/mapa")page=<MapPage router={router}/>;else if(path==="/login"||path==="/registro")page=<Login login={login}/>;else if(path.startsWith("/mi-cuenta"))page=role==="client"?<Client path={path} favs={favs} fav={fav} reset={reset}/>:<Login login={login}/>;else if(path.startsWith("/panel-negocio"))page=role==="owner"?<Owner path={path} reset={reset}/>:<Login login={login}/>;else if(path==="/para-negocios")page=<><ForBusiness router={router} compact plansLink/><BusinessPricing router={router}/></>;else if(path==="/terminos"||path==="/privacidad")page=<Legal privacy={path.includes("privacidad")}/>;const ownerPanel=path.startsWith("/panel-negocio")&&role==="owner";return <div>{!ownerPanel&&<Header router={router} role={role} path={path}/>}{page}<Footer/><MobileNav router={router} path={path}/><button className="demo-fab" onClick={()=>setDemo(true)}><Sparkles/> Modo demo</button>{demo&&<div className="modal-backdrop" onClick={()=>setDemo(false)}><section className="demo-modal" onClick={e=>e.stopPropagation()}><button className="close" onClick={()=>setDemo(false)}><X/></button><span className="eyebrow">Guía de presentación</span><h2>Recorre RadarLocal</h2><ol>{["Busca un rubro","Abre un perfil con datos e imagen reales","Guárdalo en favoritos","Consulta su fuente original","Entra al panel de Mochomos","Crea una promoción de ejemplo","Consulta estadísticas simuladas"].map((x,i)=><li key={x}><span>{i+1}</span>{x}</li>)}</ol><button className="btn primary" onClick={()=>login("client")}><User/> Entrar como cliente</button><button className="btn dark" onClick={()=>login("owner")}><Store/> Entrar como negocio</button><button className="btn ghost" onClick={reset}><RotateCcw/> Restablecer datos</button></section></div>}</div>}

function Header({router,role,path}:{router:any;role:string;path:string}){const[open,setOpen]=useState(false);const headRef=useRef<HTMLElement>(null),tabsRef=useRef<HTMLDivElement>(null);const[today,setToday]=useState("");useEffect(()=>{const d=new Date().toLocaleDateString("es-MX",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).replace(/,/g,"");setToday(d.charAt(0).toUpperCase()+d.slice(1))},[]);useEffect(()=>{const el=headRef.current;if(!el)return;const ro=new ResizeObserver(()=>document.documentElement.style.setProperty("--topbar-h",el.offsetHeight+"px"));ro.observe(el);return()=>ro.disconnect()},[]);useEffect(()=>{if(!open)return;const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape")setOpen(false)};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[open]);useEffect(()=>{const el=tabsRef.current,a=el?.querySelector<HTMLElement>(".active");if(el&&a)el.scrollLeft=a.offsetLeft-(el.clientWidth-a.offsetWidth)/2},[path]);const nav2=(p:string)=>{setOpen(false);go(router,p)};const account=role==="owner"?"/panel-negocio":role?"/mi-cuenta":"/login";return <header className="topbar" ref={headRef}><div className="container header-inner"><div className="head-info"><span className="location"><MapPin/> Cd. Chihuahua, Chihuahua, México</span>{today&&<span className="head-date"><CalendarDays/> {today}</span>}</div><Logo size={76}/><div className="header-actions"><button className="btn ghost" onClick={()=>nav2(account)}><User/>{role?"Mi panel":"Iniciar sesión"}</button><button className="btn primary" onClick={()=>nav2("/registro")}><Store/> Prueba el panel</button></div><div className="menu-wrap"><button className="menu-toggle" aria-label={open?"Cerrar menú":"Abrir menú"} aria-expanded={open} aria-controls="main-menu" onClick={()=>setOpen(o=>!o)}>{open?<X/>:<Menu/>}</button>{open&&<><div className="menu-backdrop" onClick={()=>setOpen(false)}/><nav id="main-menu" className="menu-list"><button className={path==="/eventos"?"active":""} onClick={()=>nav2("/eventos")}><Ticket/> Eventos</button><button className={path==="/promociones"?"active":""} onClick={()=>nav2("/promociones")}><Tag/> Promociones</button><hr/><button onClick={()=>nav2(account)}><User/>{role?"Mi panel":"Iniciar sesión"}</button><button onClick={()=>nav2("/registro")}><Store/> Prueba el panel</button></nav></>}</div></div><nav className="head-nav" aria-label="Secciones"><div className="container" ref={tabsRef}>
  <button className={path==="/"?"active":""} style={{"--cat":"#073b66"} as any} aria-label="Inicio" aria-current={path==="/"?"page":undefined} onClick={()=>nav2("/")}><House/></button>
  {categories.map(c=>{const href="/categorias/"+c.slug,active=path===href;return <button key={c.id} className={active?"active":""} style={{"--cat":c.color} as any} aria-current={active?"page":undefined} onClick={()=>nav2(href)}>{c.name}</button>})}
  {nav.map(n=>{const active=path===n.href,cta=n.href==="/para-negocios";return <button key={n.href} className={`${active?"active":""}${cta?" head-nav-cta":""}`} style={{"--cat":cta?"#e2553b":n.color||"#10bfc4"} as any} aria-current={active?"page":undefined} onClick={()=>nav2(n.href)}>{n.label}</button>})}
</div></nav></header>}
function MobileNav({router,path}:{router:any;path:string}){return <nav className="mobile-nav">{[["/","Inicio",Compass],["/explorar","Explorar",Search],["/eventos","Eventos",Ticket],["/mapa","Mapa",MapPin],["/mi-cuenta/favoritos","Guardados",Heart],["/login","Cuenta",User]].map(([p,l,I]:any)=><button key={p} className={path===p?"active":""} aria-current={path===p?"page":undefined} onClick={()=>go(router,p)}><I/><span>{l}</span></button>)}</nav>}

function Home({router,favs,fav}:{router:any;favs:string[];fav:(x:string)=>void}){
  const[q,setQ]=useState("");
  const search=(term:string)=>go(router,"/explorar?q="+encodeURIComponent(term));
  const poll=usePoll(),pollRef=useRef<HTMLElement>(null),[pollGone,setPollGone]=useState(false);
  useEffect(()=>{const el=pollRef.current;if(!el)return;const io=new IntersectionObserver(([e])=>setPollGone(!e.isIntersecting&&e.boundingClientRect.top<0));io.observe(el);return()=>io.disconnect()},[]);
  return <main className="home-page">
    <Sponsored router={router} strip/>
    <div className="container home-layout">
      <aside className="home-side" aria-label="Encuesta y anuncios">
        <WeeklyPoll s={poll} cardRef={pollRef}/>
        <SideAds router={router}/>
      </aside>
      <section className="home-hero"><div className="home-hero-copy">
        <span className="hello">Hola, Chihuahua 👋</span>
        <h1>¿Qué se te <em>antoja</em> hoy?</h1>
        <p>Si ya sabes qué buscas, búscalo. Si no, aquí te damos ideas.</p>
        <div className="cravings">{cravings.map(c=><button key={c.label} onClick={()=>search(c.q)}><span aria-hidden="true">{c.emoji}</span>{c.label}</button>)}</div>
        <form className="soft-search" onSubmit={e=>{e.preventDefault();search(q)}}><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="O busca algo en específico…" aria-label="Buscar en RadarLocal"/><button aria-label="Buscar"><ArrowRight/></button></form>
        <small className="no-signup"><Check/> Sin registro. Tus favoritos se guardan en este celular.</small>
      </div></section>
      <div className="home-rest">
        <WeeklyPromos router={router}/>
        <Newcomers router={router}/>
        <TeamTops router={router} favs={favs} fav={fav}/>
      </div>
    </div>
    <ForBusiness router={router} compact/>
    <PollDock s={poll} show={pollGone}/>
  </main>
}

// Anuncios en la barra lateral. Son ejemplos: ningún negocio ha contratado este espacio.
function SideAds({router}:{router:any}){return <div className="side-ads">
  <span className="side-ads-label">Anuncios</span>
  <Carousel vertical cols={2} gridClass="side-ads-track" fillUntil=".home-rest .tops-grid">{sideAds.flatMap(a=>{const b=businesses.find(x=>x.id===a.id);return b?[{...a,b}]:[]}).map(({b,tagline})=><button key={b.id} className="side-ad" onClick={()=>go(router,"/negocio/"+b.slug)}>
    <span className="side-ad-img" style={{backgroundImage:`url("${b.imageUrl}")`}}><span className="paid-badge">Anuncio</span></span>
    <span className="side-ad-body"><small>{b.categoryId==="food"?"Restaurante":categories.find(c=>c.id===b.categoryId)?.name} · {b.zone}</small><b>{b.name}</b><span>{tagline}</span><em>Ver restaurante <ArrowRight/></em></span>
  </button>)}
  <button className="side-ad-slot" onClick={()=>go(router,"/para-negocios")}><Store/><b>Tu negocio aquí</b><span>Aparece junto a la encuesta que todos ven.</span><em>Anunciarme <ArrowRight/></em></button></Carousel>
</div>}

function usePoll(){
  const{poll,daysLeft}=useMemo(()=>weeklyPoll(),[]);
  const key="rl-poll-"+poll.id;
  const[vote,setVote]=useState("");
  useEffect(()=>{try{setVote(localStorage.getItem(key)||"")}catch{}},[key]);
  const choose=(id:string)=>{setVote(id);try{if(id)localStorage.setItem(key,id);else localStorage.removeItem(key)}catch{}};
  return {poll,daysLeft,vote,choose};
}
type PollState=ReturnType<typeof usePoll>;

function PollBody({s,id}:{s:PollState;id:string}){
  const{poll,daysLeft,vote,choose}=s;
  const counts=poll.options.map(o=>o.votes+(o.id===vote?1:0)),total=counts.reduce((a,b)=>a+b,0),top=Math.max(...counts);
  return <>
    <h2 id={id}>{poll.question}</h2>
    {vote?<ol className="poll-results" aria-live="polite">{poll.options.map((o,i)=>{const pct=Math.round(counts[i]/total*100);return <li key={o.id} className={`${o.id===vote?"mine":""} ${counts[i]===top?"lead":""}`}><div><span><span aria-hidden="true">{o.emoji}</span> {o.label}{o.id===vote&&<em>Tu voto</em>}</span><b>{pct}%</b></div><i style={{width:pct+"%"}}/></li>})}</ol>
    :<div className="poll-options">{poll.options.map(o=><button key={o.id} onClick={()=>choose(o.id)}><span aria-hidden="true">{o.emoji}</span>{o.label}</button>)}</div>}
    <footer>{vote?<button onClick={()=>choose("")}><RotateCcw/> Cambiar mi voto</button>:<span>Sin registro · ves resultados al votar</span>}<span><Clock3/> Nueva pregunta en {daysLeft} {daysLeft===1?"día":"días"}</span></footer>
    <p className="poll-note">Tu voto se guarda en este dispositivo.</p>
  </>
}

function WeeklyPoll({s,cardRef}:{s:PollState;cardRef:RefObject<HTMLElement|null>}){
  const total=s.poll.options.reduce((a,o)=>a+o.votes,0)+(s.vote?1:0);
  return <aside ref={cardRef} className="poll-card" aria-labelledby="poll-question">
    <div className="poll-top"><span className="poll-label"><Vote/> Encuesta de la semana</span><small>{s.vote?`${total} votos`:"Vota con un clic"}</small></div>
    <PollBody s={s} id="poll-question"/>
  </aside>
}

// Encuesta flotante: aparece cuando la del inicio sale de pantalla, para que siempre esté a la vista.
function PollDock({s,show}:{s:PollState;show:boolean}){
  const[open,setOpen]=useState(false);
  return <div className={`poll-dock ${show?"show":""} ${open?"open":""}`} aria-hidden={!show}>
    {open?<aside className="poll-card" aria-labelledby="poll-dock-question">
      <div className="poll-top"><span className="poll-label"><Vote/> Encuesta de la semana</span><button className="poll-min" onClick={()=>setOpen(false)} aria-label="Minimizar encuesta" tabIndex={show?0:-1}><ChevronDown/></button></div>
      <PollBody s={s} id="poll-dock-question"/>
    </aside>
    :<button className="poll-pill" onClick={()=>setOpen(true)} tabIndex={show?0:-1}><Vote/><span><b>Encuesta<span className="pill-long"> de la semana</span></b><small>{s.vote?"Ver resultados":s.poll.question}</small></span>{!s.vote&&<i aria-hidden="true"/>}</button>}
  </div>
}

function Newcomers({router}:{router:any}){return <section className="section newcomers"><div className="container">
  <div className="section-head"><div><span className="eyebrow">Emprendiendo</span><h2>Recién abiertos, dales una probada</h2><p className="section-sub">Negocios con menos de 6 meses. Conoce quién está detrás y qué pedir.</p></div></div>
  <Carousel cols={3} gridClass="newcomer-grid">{newcomers.map(n=><article key={n.id} className="newcomer-card" style={{"--tone":n.color} as any}>
    <div className="newcomer-top"><span className="newcomer-emoji" aria-hidden="true">{n.emoji}</span><span className="new-badge"><Sparkles/> Nuevo · {n.opened}</span></div>
    <div className="newcomer-body"><small>{n.kind} · {n.zone}</small><h3>{n.name}</h3><blockquote>“{n.story}”</blockquote><p className="newcomer-owner"><User/> {n.owner}</p><p className="newcomer-try"><b>Pídele:</b> {n.tryThis}</p></div>
  </article>)}<article className="newcomer-cta newcomer-slot"><Sparkles/><div><b>¿Acabas de abrir tu negocio?</b><span>Queremos contar tu historia y echarte la mano a arrancar.</span></div><button className="btn dark" onClick={()=>go(router,"/para-negocios")}>Quiero aparecer <ArrowRight/></button></article></Carousel>
</div></section>}

function TeamTops({router,favs,fav}:{router:any;favs:string[];fav:(x:string)=>void}){return <section className="section tops"><div className="container">
  <div className="section-head"><div><h2>TOP</h2><p className="section-sub">🔥 Lo más visitado de Chihuahua: los lugares de los que todos hablan.</p></div></div>
  <div className="tops-grid">{teamTops.map((t,n)=>{const picks=t.picks.flatMap(p=>{const b=businesses.find(x=>x.id===p.id);return b?[{...p,b}]:[]}),lead=picks[0].b;return <article key={t.id} className="top-card">
    <button className="top-cover" style={{backgroundImage:`linear-gradient(0deg,rgba(6,30,49,.7),rgba(6,30,49,0) 55%),url("${lead.imageUrl}")`}} onClick={()=>go(router,"/negocio/"+lead.slug)} aria-label={`Ver perfil de ${lead.name}`}><span><Trophy/> TOP {n+1}</span><h3>{t.title}</h3></button>
    <ol>{picks.map(({b},i)=>{const favorite=favs.includes(b.id);return <li key={b.id}><span className="top-rank">{i+1}</span><div><button onClick={()=>go(router,"/negocio/"+b.slug)}>{b.name}</button></div><button className={`top-fav ${favorite?"active":""}`} onClick={()=>fav(b.id)} aria-label={favorite?`Quitar ${b.name} de favoritos`:`Guardar ${b.name}`}><Heart fill={favorite?"currentColor":"none"}/></button></li>})}</ol>
  </article>})}</div>
</div></section>}

// Promoción que el negocio demo (Mochomos) guardó desde su panel; solo existe en este dispositivo.
function ownPromo():Promotion|null{try{const title=localStorage.getItem("rl-promos");if(!title)return null;return {id:"own",business:"Mochomos Chihuahua",title,valid:"Tu propuesta · solo en este dispositivo",category:"food",period:localStorage.getItem("rl-promo-period")==="semanal"?"semanal":"mensual"}}catch{return null}}
function usePromos(period:PromoPeriod){const[own,setOwn]=useState<Promotion|null>(null);useEffect(()=>{setOwn(ownPromo())},[]);return [...(own?.period===period?[own]:[]),...promotions.filter(p=>p.period===period)]}
// Promociones de la semana en el inicio. Son ejemplos: ningún negocio ha propuesto estas ofertas.
function WeeklyPromos({router}:{router:any}){const weekly=usePromos("semanal").slice(0,4);return <section className="sponsored-section weekly-promos"><div className="container"><div className="sponsored-head"><div><h2>Promociones de la semana</h2></div><button className="btn white" onClick={()=>go(router,"/promociones")}>Ver todas <ArrowRight/></button></div><Carousel>{weekly.map(p=>{const b=businesses.find(x=>x.name===p.business);if(!b)return null;return <button key={p.id} className={`sponsored-card ${b.cover}`} title={p.title} aria-label={`${b.name}: ${p.title}`} style={{backgroundImage:`linear-gradient(0deg,rgba(2,24,39,.7),rgba(2,24,39,0) 55%),url("${b.imageUrl}")`}} onClick={()=>go(router,"/negocio/"+b.slug)}><span className="paid-badge">{p.id==="own"?"Tu promoción":"Promo de la semana"}</span>{p.deal&&<span className="deal-badge"><strong>{p.deal}</strong>{p.dealNote&&<em>{p.dealNote}</em>}</span>}<div><h3>{b.name}</h3></div></button>})}<button className="side-ad-slot strip-slot" onClick={()=>go(router,"/para-negocios")}><Tag/><b>Tu promoción aquí</b><span>Aparece en Promociones de la semana.</span><em>Anunciarme <ArrowRight/></em></button></Carousel></div></section>}
// Carrusel de tarjetas: 4 visibles del mismo tamaño y flechas para ver las que siguen (p. ej. el espacio "Tu negocio aquí").
function Carousel({children,cols=4,gridClass="sponsored-grid",vertical=false,fillUntil}:{children:React.ReactNode;cols?:number;gridClass?:string;vertical?:boolean;fillUntil?:string}){const grid=useRef<HTMLDivElement>(null),[edge,setEdge]=useState({start:true,end:false}),[h,setH]=useState(0);const track=()=>{const g=grid.current;if(!g)return;const pos=vertical?g.scrollTop:g.scrollLeft,size=vertical?g.clientHeight:g.clientWidth,full=vertical?g.scrollHeight:g.scrollWidth;setEdge({start:pos<=4,end:pos+size>=full-4})};
  // En vertical, el alto visible es el de las primeras `cols` tarjetas; con `fillUntil` (en escritorio) se estira hasta donde termina ese elemento.
  const measure=()=>{const g=grid.current;if(!g||!vertical)return;const kids=[...g.children].slice(0,cols) as HTMLElement[];let next=kids.reduce((t,k)=>t+k.offsetHeight,0)+(kids.length-1)*12+8;const stop=fillUntil?document.querySelector(fillUntil):null;if(stop&&window.innerWidth>1050)next=Math.max(next,stop.getBoundingClientRect().bottom-g.getBoundingClientRect().top-8);setH(Math.round(next))};
  useEffect(()=>{const update=()=>{measure();track()};update();window.addEventListener("resize",update);const stop=fillUntil?document.querySelector(".home-rest"):null,ro=stop?new ResizeObserver(update):null;if(stop)ro!.observe(stop);return()=>{window.removeEventListener("resize",update);ro?.disconnect()}},[]);
  const slide=(dir:number)=>{const g=grid.current,first=g?.firstElementChild as HTMLElement|null;if(g&&first)g.scrollBy(vertical?{top:dir*(first.offsetHeight+12),behavior:"smooth"}:{left:dir*(first.offsetWidth+16),behavior:"smooth"})};
  return <div className={`strip-carousel${vertical?" vertical":""}`}><button type="button" className="strip-arrow prev" onClick={()=>slide(-1)} disabled={edge.start} aria-label="Anterior">{vertical?<ChevronUp/>:<ChevronLeft/>}</button><div className={`${gridClass} carousel-track`} style={{"--cols":cols,...(vertical&&h?{"--h":h+"px"}:{})} as React.CSSProperties} ref={grid} onScroll={track}>{children}</div><button type="button" className="strip-arrow next" onClick={()=>slide(1)} disabled={edge.end} aria-label="Siguiente">{vertical?<ChevronDown/>:<ChevronRight/>}</button></div>}
function Sponsored({router,strip=false}:{router:any;strip?:boolean}){const ads=[businesses[0],businesses[2],businesses[4],businesses[6]];return <section className={`sponsored-section${strip?" sponsored-strip":""}`}><div className="container"><div className="sponsored-head">{!strip&&<div><span className="ad-label">Anuncios</span><h2>Visibilidad para tu negocio</h2><p>Así se verían los espacios destacados. Ningún negocio ha contratado este lugar.</p></div>}</div>{strip?<Carousel>{ads.map(b=><button key={b.id} className={`sponsored-card ${b.cover}`} style={{backgroundImage:`linear-gradient(0deg,rgba(2,24,39,${strip?".7":".88"}),rgba(2,24,39,${strip?"0) 55%":".08)"}),url("${b.imageUrl}")`}} onClick={()=>go(router,"/negocio/"+b.slug)}><span className="paid-badge">Ubicación destacada</span><div><small>{categories.find(c=>c.id===b.categoryId)?.name}</small><h3>{b.name}</h3><p>{b.shortDescription}</p><b>Ver negocio <ArrowRight/></b></div></button>)}<button className="side-ad-slot strip-slot" onClick={()=>go(router,"/para-negocios")}><Store/><b>Tu negocio aquí</b><span>Aparece en esta cintilla que todos ven.</span><em>Anunciarme <ArrowRight/></em></button></Carousel>:<div className="sponsored-grid">{ads.map(b=><button key={b.id} className={`sponsored-card ${b.cover}`} style={{backgroundImage:`linear-gradient(0deg,rgba(2,24,39,${strip?".7":".88"}),rgba(2,24,39,${strip?"0) 55%":".08)"}),url("${b.imageUrl}")`}} onClick={()=>go(router,"/negocio/"+b.slug)}><span className="paid-badge">Ubicación destacada</span><div><small>{categories.find(c=>c.id===b.categoryId)?.name}</small><h3>{b.name}</h3><p>{b.shortDescription}</p><b>Ver negocio <ArrowRight/></b></div></button>)}</div>}</div></section>}


function BusinessCard({b,router,favorite,fav}:{b:Business;router:any;favorite:boolean;fav:(x:string)=>void}){const cat=categories.find(c=>c.id===b.categoryId)!;return <article className="business-card"><button className={`cover ${b.cover}`} style={{backgroundImage:`url("${b.imageUrl}")`}} onClick={()=>go(router,"/negocio/"+b.slug)} aria-label={`Ver perfil de ${b.name}`}><small>Imagen publicada · fuente en perfil</small></button><button className={`heart ${favorite?"active":""}`} onClick={()=>fav(b.id)} aria-label={favorite?`Quitar ${b.name} de favoritos`:`Guardar ${b.name}`}><Heart fill={favorite?"currentColor":"none"}/></button><div className="business-body"><span className="cat-label">{cat.name}</span><h3><button onClick={()=>go(router,"/negocio/"+b.slug)}>{b.name}</button></h3><p>{b.shortDescription}</p><div className="card-meta"><span><MapPin/> {b.zone}</span><span><small>Datos con fuente</small></span></div></div></article>}
function PromoCard({p}:{p:Promotion}){const business=businesses.find(b=>b.name===p.business);return <article className={`promo-card promo-${p.category}`}><div>{p.deal?<span className="deal-badge inline"><strong>{p.deal}</strong>{p.dealNote&&<em>{p.dealNote}</em>}</span>:<Tag/>}<h3>{p.title}</h3><p>{p.business}</p></div><footer><span>{p.valid}</span>{business&&<a className="btn white" href={`/negocio/${business.slug}`}>Ver perfil <ArrowRight/></a>}</footer></article>}

// Filtros elegidos por el negocio demo (Mochomos) desde su panel; se guardan solo en este dispositivo.
const ownerBusinessId="food-1";
function savedFilters():string[]|null{try{const v=JSON.parse(localStorage.getItem("rl-filters")||"null");return Array.isArray(v)?v.filter((x):x is string=>typeof x==="string"):null}catch{return null}}
function FilterChips({options,value,onChange,disabled=false,limit=0}:{options:{id:string;label:string}[];value:string[];onChange:(v:string[])=>void;disabled?:boolean;limit?:number}){const[all,setAll]=useState(false);const extra=limit&&options.length>limit?options.length-limit:0;const shown=extra&&!all?options.filter((o,i)=>i<limit||value.includes(o.id)):options;return <div className="filter-chips">{shown.map(o=>{const on=value.includes(o.id);return <label key={o.id} className={on?"on":""}><input type="checkbox" checked={on} disabled={disabled} onChange={()=>onChange(on?value.filter(x=>x!==o.id):[...value,o.id])}/>{on&&<Check/>}{o.label}</label>})}{extra>0&&<button type="button" className="chips-more" onClick={()=>setAll(x=>!x)}>{all?"Ver menos":`Ver más (${extra})`}</button>}</div>}
// Sin rubro elegido, los filtros de tipo se agrupan por rubro en secciones plegables para no mostrarlos todos a la vez.
function TypeGroups({value,onChange}:{value:string[];onChange:(v:string[])=>void}){const[open,setOpen]=useState<string[]>([]);return <div className="type-groups">{categories.filter(c=>c.filters.length).map(c=>{const isOpen=open.includes(c.id),n=c.filters.filter(f=>value.includes(f.id)).length;return <div key={c.id} className={`type-group${isOpen?" open":""}`} style={{"--cat":c.color} as React.CSSProperties}><button type="button" aria-expanded={isOpen} onClick={()=>setOpen(o=>isOpen?o.filter(x=>x!==c.id):[...o,c.id])}><span>{c.name}</span>{n>0&&<em>{n}</em>}<ChevronDown/></button>{isOpen&&<FilterChips options={c.filters} value={value} onChange={onChange} limit={6}/>}</div>})}</div>}
function Explore({router,initial,favs,fav}:{router:any;initial:string;favs:string[];fav:(x:string)=>void}){const[q,setQ]=useState(""),[cat,setCat]=useState(categories.find(c=>c.slug===initial)?.id||""),[zone,setZone]=useState(""),[sort,setSort]=useState("study"),[filtersOpen,setFiltersOpen]=useState(false),[types,setTypes]=useState<string[]>([]),[ownerFilters,setOwnerFilters]=useState<string[]|null>(null);useEffect(()=>{setOwnerFilters(savedFilters())},[]);useEffect(()=>{setQ(new URLSearchParams(window.location.search).get("q")||"");setCat(categories.find(c=>c.slug===initial)?.id||"");setTypes([])},[initial]);const typeOptions=categories.find(c=>c.id===cat)?.filters||[];const norm=(x:string)=>x.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();const results=useMemo(()=>businesses.filter(b=>(!q||norm([b.name,b.shortDescription,b.zone,...b.tags,...b.services].join(" ")).includes(norm(q)))&&(!cat||b.categoryId===cat)&&(!zone||b.zone===zone)&&(!types.length||types.some(x=>(b.id===ownerBusinessId&&ownerFilters?ownerFilters:b.filters).includes(x)))).sort((a,b)=>sort==="name"?a.name.localeCompare(b.name,"es"):sort==="name-desc"?b.name.localeCompare(a.name,"es"):0),[q,cat,zone,sort,types,ownerFilters]);const clear=()=>{setQ("");setCat("");setZone("");setTypes([]);router.replace("/explorar")};return <main className="explore-page"><div className="container"><div className="explore-title"><div><span className="eyebrow">Directorio RadarLocal</span><h1>Encuentra un negocio</h1><p>{results.length} {results.length===1?"perfil documentado":"perfiles documentados"} en Chihuahua y alrededores.</p></div><button className="btn filter-mobile" onClick={()=>setFiltersOpen(x=>!x)}><SlidersHorizontal/> Filtros</button></div><div className="search-wide"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Busca por nombre, rubro o servicio"/><button className="btn primary" onClick={()=>router.replace("/explorar?q="+encodeURIComponent(q))}>Buscar</button></div><div className="explore-layout"><aside className={`filters ${filtersOpen?"open":""}`}><div className="filter-head"><b>Filtros</b><button onClick={clear}>Limpiar</button></div><label>Rubro<select value={cat} onChange={e=>{setCat(e.target.value);setTypes([])}}><option value="">Todos los rubros</option>{categories.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><fieldset className="type-filters"><legend>Tipo</legend>{cat?<FilterChips key={cat} options={typeOptions} value={types} onChange={setTypes} limit={6}/>:<TypeGroups value={types} onChange={setTypes}/>}</fieldset><label>Zona<select value={zone} onChange={e=>setZone(e.target.value)}><option value="">Todas las zonas</option>{[...new Set(businesses.map(b=>b.zone))].map(z=><option key={z} value={z}>{z}</option>)}</select></label><div className="filter-note"><ShieldCheck/><p>Datos e imágenes con fuente. Confirma detalles antes de visitar.</p></div></aside><section><div className="results-head"><b>{results.length} {results.length===1?"negocio":"negocios"}</b><select aria-label="Ordenar resultados" value={sort} onChange={e=>setSort(e.target.value)}><option value="study">Orden del estudio</option><option value="name">Nombre A–Z</option><option value="name-desc">Nombre Z–A</option></select></div>{results.length?<div className="business-grid compact-grid">{results.map(b=><BusinessCard key={b.id} b={b} router={router} favorite={favs.includes(b.id)} fav={fav}/>)}</div>:<Empty clear={clear}/>}</section></div></div></main>}
function Toggle({label,value,set}:{label:string;value:boolean;set:(x:boolean)=>void}){return <label className="toggle"><span>{label}</span><input type="checkbox" checked={value} onChange={e=>set(e.target.checked)}/><i/></label>}
function Empty({clear}:{clear:()=>void}){return <div className="empty"><Search/><h2>No encontramos resultados</h2><p>Prueba otra palabra o limpia los filtros.</p><button className="btn primary" onClick={clear}>Limpiar filtros</button></div>}

function Profile({slug,favs,fav}:{slug:string;favs:string[];fav:(x:string)=>void}){const b=businesses.find(x=>x.slug===slug);if(!b)return <main className="simple-page"><div className="container"><h1>Negocio no encontrado</h1><p>El perfil que buscas no existe o ya no está disponible.</p><a className="btn primary" href="/explorar">Explorar negocios</a></div></main>;const cat=categories.find(c=>c.id===b.categoryId)!;return <main className="profile-page"><section className={`profile-cover ${b.cover}`} style={{backgroundImage:`url("${b.imageUrl}")`}}><span>{b.fictional?null:<>Imagen publicada · <a href={b.imageSource} target="_blank" rel="noopener noreferrer">ver fuente</a></>}</span></section><div className="container profile-wrap"><section className="profile-main"><div className="identity"><div className="avatar">{b.name.split(" ").slice(0,2).map(x=>x[0]).join("")}</div><div><span className="cat-label">{cat.name}</span><h1>{b.name}</h1><p>{b.shortDescription}</p><div className="card-meta"><span><MapPin/> {b.zone}, Chihuahua</span></div></div></div><Info title="Acerca de este negocio"><p>{b.shortDescription} Este perfil muestra cómo RadarLocal puede organizar su oferta para nuevos clientes.</p>{b.fictional?null:<a href={b.sourceUrl} target="_blank" rel="noopener noreferrer">Consultar fuente del negocio <ArrowRight/></a>}</Info><Info title="Productos y servicios"><div className="service-grid">{b.services.map(s=><div key={s}><span>✦</span><b>{s}</b><p>Consulta disponibilidad con el negocio.</p></div>)}</div></Info><Info title="Ubicación">{b.fictional?<p><MapPin/> {b.zone}, Chihuahua.</p>:<><p><MapPin/> {b.zone}, Chihuahua. Confirma la dirección antes de visitar.</p><a href={mapsUrl(b)} target="_blank" rel="noopener noreferrer">Buscar en Google Maps <ArrowRight/></a></>}</Info></section><aside className="contact-card"><h3>Conoce a {b.name}</h3>{!b.fictional&&<a className="btn primary" href={b.sourceUrl} target="_blank" rel="noopener noreferrer"><Globe2/> Visitar fuente <ArrowRight/></a>}<button className="btn ghost" onClick={()=>fav(b.id)}><Heart fill={favs.includes(b.id)?"currentColor":"none"}/> {favs.includes(b.id)?"Guardado":"Guardar"}</button><small>RadarLocal aún no recibe contactos reales para estos negocios.</small></aside></div></main>}
function Info({title,children}:{title:string;children:any}){return <section className="info-section"><h2>{title}</h2>{children}</section>}
function Promotions(){return <main className="simple-page"><div className="container"><span className="eyebrow">Herramienta para negocios</span><h1>Promociones</h1><p className="lead">Las mejores ofertas de los negocios de Chihuahua.</p><PromoGroup title="Promociones de la semana" note="Duran 7 días y también salen en el inicio." period="semanal"/><PromoGroup title="Promociones del mes" note="Duran todo el mes." period="mensual"/></div></main>}
function PromoGroup({title,note,period}:{title:string;note:string;period:PromoPeriod}){const list=usePromos(period);return <section className="promo-group"><div className="promo-group-head"><h2>{title}</h2><p>{note}</p></div><div className="promo-grid wide">{list.map(p=><PromoCard key={p.id} p={p}/>)}</div></section>}
function MapCanvas({business=businesses[0]}:{business?:Business}){return <GoogleBusinessMap business={business}/>}
function MapPage({router}:{router:any}){
  const[selected,setSelected]=useState(businesses[0]);
  const[userLocation,setUserLocation]=useState<MapPoint|null>(null);
  const[locationStatus,setLocationStatus]=useState<"idle"|"requesting"|"ready"|"error">("idle");
  const[locationMessage,setLocationMessage]=useState("");
  const[places,setPlaces]=useState<Record<string,MapPoint>>({});
  const updatePlaces=useCallback((found:Record<string,MapPoint>)=>setPlaces(found),[]);
  const ranked=useMemo(()=>mappable.map(b=>({business:b,distance:userLocation&&places[b.id]?straightLineKm(userLocation,places[b.id]):null})).sort((a,b)=>{
    if(!userLocation)return 0;
    if(a.distance===null)return 1;
    if(b.distance===null)return -1;
    return a.distance-b.distance;
  }),[userLocation,places]);
  const locate=()=>{
    if(!navigator.geolocation){setLocationStatus("error");setLocationMessage("Este navegador no permite consultar tu ubicación.");return}
    setLocationStatus("requesting");
    setLocationMessage("");
    navigator.geolocation.getCurrentPosition(
      position=>{setUserLocation({lat:position.coords.latitude,lng:position.coords.longitude});setLocationStatus("ready")},
      error=>{setUserLocation(null);setLocationStatus("error");setLocationMessage(error.code===1?"No diste permiso de ubicación. Puedes seguir explorando el mapa.":error.code===3?"No pudimos obtener tu ubicación a tiempo. Intenta de nuevo.":"No pudimos obtener tu ubicación. Revisa los permisos del dispositivo.")},
      {enableHighAccuracy:false,timeout:12000,maximumAge:60000}
    );
  };
  return <main className="map-page"><aside>
    <span className="eyebrow">Google Maps</span>
    <h1>{userLocation?"Lugares más cercanos":"Negocios para descubrir"}</h1>
    <p className="map-disclaimer">{userLocation?"Distancias aproximadas en línea recta entre tu ubicación y los negocios encontrados por Google.":"Activa tu ubicación para ver cuáles de estos negocios están más cerca de ti."}</p>
    <button className="btn primary locate-button" onClick={locate} disabled={locationStatus==="requesting"}><Navigation/>{locationStatus==="requesting"?"Buscando tu ubicación…":userLocation?"Actualizar mi ubicación":"Usar mi ubicación"}</button>
    {locationMessage&&<p className="location-message" role="status">{locationMessage}</p>}
    {userLocation&&<div className="map-legend"><span><i className="you"/> Tu ubicación</span>{categories.filter(category=>mappable.some(x=>x.categoryId===category.id)).map(category=><span key={category.id}><i style={{background:category.color}}/> {category.name}</span>)}</div>}
    <div className="map-list">{ranked.map(({business:b,distance},index)=><button key={b.id} onClick={()=>setSelected(b)} className={selected.id===b.id?"selected":""}><span className={`mini-cover ${b.cover}`}>{b.name[0]}</span><span><b>{b.name}</b><small>{b.zone} · {distance===null?"Ubicación por confirmar":distanceLabel(distance)}</small>{userLocation&&distance!==null&&index<3&&<em className="nearby-tag">De los más cercanos</em>}</span></button>)}</div>
  </aside><section className="map-full"><GoogleBusinessMap business={selected} listings={mappable} userLocation={userLocation} onPlacesChange={updatePlaces} onSelectBusiness={setSelected}/><div className="map-popup"><span className={`mini-cover ${selected.cover}`}>{selected.name[0]}</span><div><small>{categories.find(c=>c.id===selected.categoryId)?.name}</small><b>{selected.name}</b><span>{userLocation&&places[selected.id]?`${distanceLabel(straightLineKm(userLocation,places[selected.id]))} · en línea recta`:"Ubicación sugerida por Google Maps"}</span><button onClick={()=>go(router,"/negocio/"+selected.slug)}>Ver perfil <ArrowRight/></button><a href={mapsUrl(selected)} target="_blank" rel="noopener noreferrer">Abrir en Google Maps <ArrowRight/></a></div></div></section></main>
}

function Login({login}:{login:(x:string)=>void}){const[error,setError]=useState(""),[email,setEmail]=useState(""),[password,setPassword]=useState("");const submit=()=>{if(email==="cliente@radarlocal.mx"&&password==="DemoCliente2026!")login("client");else if(email==="negocio@radarlocal.mx"&&password==="DemoNegocio2026!")login("owner");else setError("Correo o contraseña incorrectos.")};return <main className="auth-page"><section className="auth-aside"><Logo/><div><span className="eyebrow light">RadarLocal para negocios</span><h1>Descubre y presenta tu negocio en Chihuahua.</h1><p>Recorre el directorio y prueba el panel del propietario.</p></div><small>RadarLocal · Chihuahua, México</small></section><section className="auth-card"><span className="eyebrow">Iniciar sesión</span><h2>Bienvenido a RadarLocal</h2><p>Entra para guardar tus favoritos o administrar tu negocio.</p><form onSubmit={e=>{e.preventDefault();submit()}}><label>Correo<input value={email} onChange={e=>setEmail(e.target.value)} placeholder="tucorreo@correo.com"/></label><label>Contraseña<input value={password} onChange={e=>setPassword(e.target.value)} type="password" placeholder="••••••••"/></label>{error&&<div className="error">{error}</div>}<button className="btn primary">Iniciar sesión</button></form><div className="or"><span/>o prueba rápidamente<span/></div><button className="btn demo-client" onClick={()=>login("client")}><User/> Entrar como cliente</button><button className="btn dark" onClick={()=>login("owner")}><Store/> Entrar como negocio</button></section></main>}

function Dash({items,path,router,reset,user,label,children}:{items:any[];path:string;router:any;reset:()=>void;user:string;label:string;children:any}){return <main className="dashboard"><aside className="dash-sidebar"><Logo compact/><div className="dash-user"><span>{user[0]}</span><div><b>{user}</b><small>{label}</small></div></div><nav>{items.map(({p,l,i:I,lock})=><button className={`${path===p?"active":""}${lock?" locked":""}`} key={p} onClick={()=>go(router,p)}><I/>{l}{lock&&<Lock className="nav-lock" aria-label="No incluido en tu plan"/>}</button>)}</nav><button className="logout" onClick={reset}><LogOut/> Cerrar sesión</button></aside><section className="dash-content">{children}</section></main>}
function Client({path,favs,fav,reset}:{path:string;favs:string[];fav:(x:string)=>void;reset:()=>void}){const router=useRouter(),items=[{p:"/mi-cuenta",l:"Resumen",i:LayoutDashboard},{p:"/mi-cuenta/favoritos",l:"Favoritos",i:Heart},{p:"/mi-cuenta/actividad",l:"Actividad",i:Clock3},{p:"/mi-cuenta/configuracion",l:"Configuración",i:Settings}],saved=businesses.filter(b=>favs.includes(b.id));return <Dash items={items} path={path} router={router} reset={reset} user="Mariana" label="Cuenta de cliente"><DashHead title={path.includes("favoritos")?"Tus favoritos":path.includes("configuracion")?"Preferencias":"Hola, Mariana"}/>{path.includes("favoritos")?<div className="business-grid">{saved.length?saved.map(b=><BusinessCard key={b.id} b={b} router={router} favorite fav={fav}/>):<Empty clear={()=>go(router,"/explorar")}/>}</div>:path.includes("configuracion")?<SettingsPanel/>:<div className="dashboard-cards"><article className="welcome-card"><span>Tu RadarLocal</span><h2>{favs.length} negocios guardados</h2><p>Continúa explorando opciones cerca de ti.</p><button className="btn white" onClick={()=>go(router,"/explorar")}>Explorar ahora</button></article><article className="panel-card"><h3>Actividad reciente</h3>{businesses.slice(0,3).map(b=><div className="activity-row" key={b.id}><span className={`mini-cover ${b.cover}`}>{b.name[0]}</span><div><b>{b.name}</b><small>Perfil consultado</small></div></div>)}</article></div>}</Dash>}
function DashHead({title}:{title:string}){return <div className="dash-head"><div><span className="eyebrow">Tu cuenta</span><h1>{title}</h1></div></div>}
function SettingsPanel(){const[n,setN]=useState(true),[saved,setSaved]=useState(false);return <div className="panel-card form-panel"><h3>Preferencias</h3><label>Nombre<input defaultValue="Mariana"/></label><label>Ubicación<input defaultValue="Chihuahua, Chihuahua"/></label><Toggle label="Notificaciones" value={n} set={setN}/><button className="btn primary" onClick={()=>setSaved(true)}><Check/> Guardar cambios</button>{saved&&<span className="success"><Check/> Preferencias guardadas en esta sesión</span>}</div>}

// Plan simulado del panel de negocio, para mostrar en la demo cómo se ve cada plan.
type PlanId="free"|"basic"|"featured";
const planRank:Record<PlanId,number>={free:0,basic:1,featured:2};
const planName:Record<PlanId,string>={free:"Gratuito",basic:"Básico",featured:"Plus"};
const has=(plan:PlanId,min:PlanId)=>planRank[plan]>=planRank[min];
function PlanSwitch({plan,setPlan}:{plan:PlanId;setPlan:(p:PlanId)=>void}){return <div className="plan-switch" role="group" aria-label="Simular plan"><span>Simular plan</span>{(["free","basic","featured"] as PlanId[]).map(id=><button key={id} className={plan===id?"active":""} aria-pressed={plan===id} onClick={()=>setPlan(id)}>{planName[id]}</button>)}</div>}
function Locked({title,min,gains,setPlan}:{title:string;min:PlanId;gains:string[];setPlan:(p:PlanId)=>void}){const router=useRouter();return <div className="panel-card locked-card"><span className="locked-icon"><Lock/></span><h3>{title}</h3><p>Disponible desde el plan <b>{planName[min]}</b>.</p><ul>{gains.map(x=><li key={x}><Check/>{x}</li>)}</ul><div className="locked-actions"><button className="btn primary" onClick={()=>setPlan(min)}><Sparkles/> Simular plan {planName[min]}</button><button className="btn ghost" onClick={()=>go(router,"/panel-negocio/plan")}>Ver planes</button></div></div>}
function Owner({path,reset}:{path:string;reset:()=>void}){const router=useRouter(),[plan,setPlanState]=useState<PlanId>("featured");useEffect(()=>{try{const v=localStorage.getItem("rl-demo-plan");if(v==="free"||v==="basic"||v==="featured")setPlanState(v)}catch{}},[]);const setPlan=(p:PlanId)=>{setPlanState(p);try{localStorage.setItem("rl-demo-plan",p)}catch{}};
  const items=[{p:"/panel-negocio",l:"Resumen",i:LayoutDashboard},{p:"/panel-negocio/perfil",l:"Perfil",i:Store,lock:!has(plan,"basic")},{p:"/panel-negocio/catalogo",l:"Catálogo",i:ShoppingBag,lock:!has(plan,"featured")},{p:"/panel-negocio/promociones",l:"Promociones",i:Tag,lock:!has(plan,"basic")},{p:"/panel-negocio/estadisticas",l:"Estadísticas",i:BarChart3,lock:!has(plan,"basic")},{p:"/panel-negocio/contactos",l:"Contactos",i:Phone,lock:!has(plan,"featured")},{p:"/panel-negocio/plan",l:"Plan",i:Sparkles},{p:"/panel-negocio/configuracion",l:"Configuración",i:Settings}];
  let body=<Summary plan={plan} setPlan={setPlan}/>;
  if(path.includes("/perfil"))body=<Editor plan={plan}/>;
  else if(path.includes("/catalogo"))body=has(plan,"featured")?<Catalog/>:<Locked title="Catálogo de productos y servicios" min="featured" gains={["Muestra tus productos o servicios con foto","Precios y disponibilidad","Más razones para que te contacten"]} setPlan={setPlan}/>;
  else if(path.includes("/promociones"))body=has(plan,"basic")?<PromoEditor plan={plan}/>:<Locked title="Promociones" min="basic" gains={["1 promoción mensual activa con el plan Básico","Promociones semanales y mensuales ilimitadas con el plan Plus","Las semanales salen en Promociones de la semana del inicio (Plus)"]} setPlan={setPlan}/>;
  else if(path.includes("/estadisticas"))body=has(plan,"basic")?<Analytics plan={plan} setPlan={setPlan}/>:<Locked title="Estadísticas" min="basic" gains={["Cuántas personas ven tu perfil","Clics en WhatsApp y Cómo llegar","Gráficas y contactos con el plan Plus"]} setPlan={setPlan}/>;
  else if(path.includes("/contactos"))body=has(plan,"featured")?<Contacts/>:<Locked title="Contactos" min="featured" gains={["Historial de quién te contactó y por dónde","Saber qué te trae más clientes: perfil, promoción o búsqueda"]} setPlan={setPlan}/>;
  else if(path.includes("/plan"))body=<Plans plan={plan} setPlan={setPlan}/>;
  else if(path.includes("/configuracion"))body=<SettingsPanel/>;
  return <Dash items={items} path={path} router={router} reset={reset} user="Mochomos Chihuahua" label={`Plan ${planName[plan]}`}><PlanSwitch plan={plan} setPlan={setPlan}/><DashHead title={items.find(i=>i.p===path)?.l||"Resumen"}/>{body}</Dash>}
function Metric({label,value,delta,I}:{label:string;value:string;delta:string;I:any}){return <article className="metric"><span><I/></span><small>{label}</small><b>{value}</b><em>{delta} vs. periodo anterior</em></article>}
function Chart(){return <div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activity}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="day"/><YAxis/><Tooltip/><Area type="monotone" dataKey="visits" stroke="#073B66" fill="#EAF8FA" strokeWidth={3}/><Area type="monotone" dataKey="contacts" stroke="#10BFC4" fill="transparent" strokeWidth={2}/></AreaChart></ResponsiveContainer></div>}
const searchPosition:Record<PlanId,string>={free:"Después de los planes de pago",basic:"Antes que los perfiles gratuitos",featured:"Primeros lugares en Comida y bebidas"};
function Summary({plan,setPlan}:{plan:PlanId;setPlan:(p:PlanId)=>void}){return <><div className={`plan-status plan-status-${plan}`}><div><small>Tu plan</small><b>{planName[plan]}</b></div><div><small>Posición en búsquedas</small><b>{searchPosition[plan]}</b></div><div><small>Promociones</small><b>{plan==="free"?"No incluidas":plan==="basic"?"1 mensual":"Semanales y mensuales"}</b></div><div><small>Edición del perfil</small><b>{plan==="free"?"Con ayuda del equipo":"Tú mismo"}</b></div></div>
  {plan==="free"?<Locked title="Estadísticas de tu negocio" min="basic" gains={["Visitas a tu perfil y clics en WhatsApp","Edita tu perfil tú mismo","Aparece antes que los perfiles gratuitos"]} setPlan={setPlan}/>
  :<><div className={`metrics${plan==="featured"?" metrics-5":""}`}>{plan==="featured"&&<Metric label="Visitas a tu giro" value="10,500" delta="+42%" I={Utensils}/>}<Metric label="Visitas al perfil" value={plan==="featured"?"1,284":"412"} delta={plan==="featured"?"+18%":"+6%"} I={Compass}/><Metric label="Clics en WhatsApp" value={plan==="featured"?"126":"38"} delta={plan==="featured"?"+12%":"+4%"} I={Phone}/>{plan==="featured"&&<><Metric label="Cómo llegar" value="89" delta="+7%" I={Navigation}/><Metric label="Veces guardado" value="214" delta="+24%" I={Heart}/></>}</div>
  <div className="dashboard-grid">{plan==="featured"?<article className="panel-card chart-card"><h3>Actividad de los últimos 30 días</h3><Chart/></article>:<Locked title="Gráfica de actividad" min="featured" gains={["Actividad de los últimos 30 días","Primeros lugares en tu categoría","Espacios destacados del inicio"]} setPlan={setPlan}/>}<article className="panel-card completion"><h3>Completitud del perfil</h3><div className="progress-ring">78%</div><div className="progress"><i/></div>{["Agregar más fotografías","Confirmar horarios","Crear una promoción"].map(x=><p key={x}><span/> {x}<ChevronRight/></p>)}</article></div></>}</>}
function Editor({plan}:{plan:PlanId}){const[requested,setRequested]=useState(false);const own=businesses.find(b=>b.id===ownerBusinessId)!,ownCat=categories.find(c=>c.id===own.categoryId)!;const[filters,setFilters]=useState<string[]>(own.filters);useEffect(()=>{const v=savedFilters();if(v)setFilters(v)},[]);const filterField=(locked:boolean)=><fieldset className="full type-filters"><legend>Filtros de búsqueda</legend><p>{locked?"Filtros donde aparece tu negocio en ":"Elige en qué filtros de "}<b>{ownCat.name}</b>{locked?".":" aparece tu negocio cuando la gente busca."}</p><FilterChips options={ownCat.filters} value={filters} onChange={v=>{setFilters(v);setSaved(false)}} disabled={locked}/></fieldset>;const[description,setDescription]=useState("Cocina sonorense de autor, cortes y mariscos en Distrito Uno."),[saved,setSaved]=useState(false);useEffect(()=>{const value=localStorage.getItem("rl-profile");if(value)setDescription(value)},[]);if(plan==="free")return <div className="panel-card form-panel"><h3>Información de Mochomos Chihuahua</h3><p className="readonly-note"><Lock/> Con el plan Gratuito tu ficha la administra el equipo de RadarLocal. Para editarla tú mismo, cambia al plan Básico.</p><div className="form-grid"><label>Nombre comercial<input value="Mochomos Chihuahua" readOnly/></label><label>Rubro<input value="Comida y bebidas" readOnly/></label><label className="full">Descripción<textarea value={description} readOnly/></label><label>Zona<input value="Distrito Uno" readOnly/></label>{filterField(true)}</div><button className="btn ghost" onClick={()=>setRequested(true)}>Solicitar un cambio al equipo</button>{requested&&<span className="success"><Check/> Solicitud enviada</span>}</div>;return <div className="panel-card form-panel"><h3>Información de Mochomos Chihuahua</h3><p>Edición local de presentación. No cambia el perfil público ni representa al negocio.</p><div className="form-grid"><label>Nombre comercial<input value="Mochomos Chihuahua" readOnly/></label><label>Rubro<input value="Comida y bebidas" readOnly/></label><label className="full">Descripción<textarea value={description} onChange={e=>{setDescription(e.target.value);setSaved(false)}}/></label><label>Zona<input value="Distrito Uno" readOnly/></label>{filterField(false)}</div><button className="btn primary" onClick={()=>{localStorage.setItem("rl-profile",description);localStorage.setItem("rl-filters",JSON.stringify(filters));setSaved(true)}}><Check/> Guardar en este dispositivo</button>{saved&&<span className="success"><Check/> Borrador local guardado</span>}</div>}
function Catalog(){const[items,setItems]=useState(["Cortes","Mariscos","Reservaciones"]);return <div className="panel-card"><div className="panel-title"><h3>Productos y servicios</h3><button className="btn primary" onClick={()=>setItems([...items,"Nuevo servicio"])}><Plus/> Agregar</button></div><div className="catalog-list">{items.map((x,i)=><div key={i}><span className="product-photo">{x[0]}</span><div><b>{x}</b><small>Disponibilidad y precio por confirmar</small></div><button className="btn ghost" onClick={()=>{const next=prompt("Editar servicio",x);if(next?.trim())setItems(items.map((v,index)=>index===i?next.trim():v))}}>Editar</button></div>)}</div></div>}
// Eventos: misma estructura que Promociones, con acento morado para distinguir que es la agenda de eventos.
// Los eventos son datos simulados; los que crea el visitante se guardan solo en este dispositivo.
type EventStatus="proximos"|"pasados"|"todos";
const eventCat=(id:string)=>eventCategories.find(c=>c.id===id)||eventCategories[0];
const isPast=(e:RadarEvent,now:number)=>new Date(e.end).getTime()<now;
const eventCover=(url:string)=>({backgroundImage:`linear-gradient(0deg,rgba(25,10,35,.75),rgba(25,10,35,0) 60%),url("${url}")`});
function savedEvents():RadarEvent[]{try{const v=JSON.parse(localStorage.getItem("rl-events")||"[]");return Array.isArray(v)?v:[]}catch{return []}}
function eventDay(iso:string){return new Date(iso).toLocaleDateString("es-MX",{weekday:"long",day:"numeric",month:"long"})}
function eventTime(iso:string){return new Date(iso).toLocaleTimeString("es-MX",{hour:"numeric",minute:"2-digit"})}
function eventSchedule(e:RadarEvent){return e.start.slice(0,10)===e.end.slice(0,10)?`${eventTime(e.start)} – ${eventTime(e.end)}`:`${eventTime(e.start)} · termina el ${eventDay(e.end)}, ${eventTime(e.end)}`}
function DateTile({iso}:{iso:string}){const d=new Date(iso);return <span className="event-date-tile"><em>{d.toLocaleDateString("es-MX",{month:"short"}).replace(".","")}</em><strong>{d.getDate()}</strong></span>}
function EventMeta({e,more=false}:{e:RadarEvent;more?:boolean}){return <ul className="event-meta"><li><CalendarDays/><span className="cap">{eventDay(e.start)}</span></li><li><Clock3/>{eventSchedule(e)}</li><li>{e.mode==="virtual"?<Video/>:<MapPin/>}{e.location}</li>{more&&<><li><Store/>Organiza: {e.organizer}</li><li><Tag/>{e.price}</li></>}</ul>}
function EventCard({e,past,open}:{e:RadarEvent;past:boolean;open:(e:RadarEvent)=>void}){const c=eventCat(e.category);return <article className={`event-card${past?" past":""}`}><div className="event-cover" style={eventCover(e.imageUrl)}><span className="event-tag"><Ticket/>{past?"Finalizado":e.id.startsWith("own")?"Tu evento":"Evento"}</span><DateTile iso={e.start}/><span className="event-cat" style={{"--cat":c.color} as any}><i/>{c.label}</span></div><div className="event-body"><h3>{e.title}</h3><EventMeta e={e}/><footer><span className={`event-mode ${e.mode}`}>{e.mode==="virtual"?"Virtual":"Presencial"}</span><button className="btn event" onClick={()=>open(e)}>Ver más <ArrowRight/></button></footer></div></article>}
function EventModal({e,past,close}:{e:RadarEvent;past:boolean;close:()=>void}){const c=eventCat(e.category),business=businesses.find(b=>b.name===e.organizer);useEffect(()=>{const onKey=(k:KeyboardEvent)=>{if(k.key==="Escape")close()};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[close]);return <div className="modal-backdrop" onClick={close}><section className="event-modal" role="dialog" aria-modal="true" aria-label={e.title} onClick={x=>x.stopPropagation()}><div className="event-cover" style={eventCover(e.imageUrl)}><span className="event-tag"><Ticket/>{past?"Finalizado":"Evento"}</span><DateTile iso={e.start}/><span className="event-cat" style={{"--cat":c.color} as any}><i/>{c.label}</span></div><button className="close" aria-label="Cerrar" onClick={close}><X/></button><div className="event-modal-body"><h2>{e.title}</h2><p>{e.description}</p><EventMeta e={e} more/><div className="event-modal-actions">{past?<span className="event-closed">Este evento ya terminó.</span>:<button className="btn event" onClick={close}><Check/> Me interesa</button>}{business&&<a className="btn ghost" href={`/negocio/${business.slug}`}>Ver negocio <ArrowRight/></a>}</div></div></section></div>}
const statusOptions:[EventStatus,string][]=[["proximos","Próximos"],["pasados","Pasados"],["todos","Todos"]];
function EventFilters({q,setQ,cat,setCat,status,setStatus}:{q:string;setQ:(v:string)=>void;cat:string;setCat:(v:string)=>void;status:EventStatus;setStatus:(v:EventStatus)=>void}){return <div className="event-filters" role="search"><label className="event-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar evento, lugar u organizador" aria-label="Buscar eventos"/>{q&&<button type="button" aria-label="Borrar búsqueda" onClick={()=>setQ("")}><X/></button>}</label><select value={cat} onChange={e=>setCat(e.target.value)} aria-label="Categoría"><option value="">Todas las categorías</option>{eventCategories.map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select><div className="event-status" role="group" aria-label="Estado">{statusOptions.map(([id,l])=><button key={id} type="button" className={status===id?"on":""} aria-pressed={status===id} onClick={()=>setStatus(id)}>{l}</button>)}</div></div>}
const emptyEvent={title:"",description:"",category:"musica",start:"",end:"",mode:"presencial" as EventMode,location:""};
function EventForm({onSave,onCancel}:{onSave:(e:RadarEvent)=>void;onCancel:()=>void}){const[f,setF]=useState(emptyEvent),[saved,setSaved]=useState("");const edit=(k:keyof typeof emptyEvent,v:string)=>{setF({...f,[k]:v});setSaved("")};const endError=f.start&&f.end&&f.end<=f.start?"La hora de fin debe ser posterior al inicio.":"";const valid=!!(f.title.trim()&&f.start&&f.end&&!endError);const today=new Date().toISOString().slice(0,10);const preview:RadarEvent={id:"own-preview",title:f.title.trim()||"Título de tu evento",description:f.description.trim()||"Sin descripción.",category:f.category,start:f.start||today+"T19:00",end:f.end||f.start||today+"T21:00",mode:f.mode,location:f.location.trim()||(f.mode==="virtual"?"Transmisión en línea":"Ubicación por confirmar"),organizer:"Tu negocio",imageUrl:"/brand/home-bg.jpg",price:"Por definir"};const save=(x:React.FormEvent)=>{x.preventDefault();if(!valid)return;onSave({...preview,id:"own-"+Date.now()});setSaved(preview.title);setF(emptyEvent)};return <div className="event-editor"><form className="panel-card form-panel" onSubmit={save}><div className="event-editor-head"><h3><CalendarPlus/> Crear evento</h3><button type="button" className="close" aria-label="Cerrar formulario" onClick={onCancel}><X/></button></div><p>Simulación: el evento se guarda solo en este dispositivo.</p><label>Título<input value={f.title} onChange={e=>edit("title",e.target.value)} placeholder="Ej. Noche de jazz en vivo" required/></label><label>Descripción<textarea value={f.description} onChange={e=>edit("description",e.target.value)} placeholder="¿Qué van a vivir los asistentes?"/></label><div className="event-row"><label>Inicio<input type="datetime-local" value={f.start} onChange={e=>edit("start",e.target.value)} required/></label><label>Fin<input type="datetime-local" value={f.end} min={f.start||undefined} onChange={e=>edit("end",e.target.value)} required/></label></div>{endError&&<p className="event-error">{endError}</p>}<fieldset className="type-filters promo-period"><legend>Modalidad</legend><div className="filter-chips">{(["presencial","virtual"] as EventMode[]).map(m=>{const on=f.mode===m;return <label key={m} className={on?"on":""}><input type="radio" name="event-mode" checked={on} onChange={()=>edit("mode",m)}/>{on?<Check/>:m==="virtual"?<Video/>:<MapPin/>}{m==="virtual"?"Virtual":"Presencial"}</label>})}</div></fieldset><div className="event-row"><label>{f.mode==="virtual"?"Enlace o plataforma":"Ubicación"}<input value={f.location} onChange={e=>edit("location",e.target.value)} placeholder={f.mode==="virtual"?"Ej. Zoom, Google Meet":"Ej. Av. Juárez 123, Centro"}/></label><label>Categoría<select value={f.category} onChange={e=>edit("category",e.target.value)}>{eventCategories.map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label></div><button className="btn event" type="submit" disabled={!valid}><Plus/> Guardar evento</button>{saved&&<span className="success"><Check/> Evento guardado: {saved}</span>}</form><div className="panel-card event-preview"><h3>Vista previa</h3><EventCard e={preview} past={false} open={()=>{}}/></div></div>}
function Events(){const[list,setList]=useState<RadarEvent[]|null>(null),[now,setNow]=useState(0),[q,setQ]=useState(""),[cat,setCat]=useState(""),[status,setStatus]=useState<EventStatus>("proximos"),[creating,setCreating]=useState(false),[open,setOpen]=useState<RadarEvent|null>(null);useEffect(()=>{setList([...savedEvents(),...mockEvents()]);setNow(Date.now())},[]);const close=useCallback(()=>setOpen(null),[]);const reset=()=>{setQ("");setCat("");setStatus("proximos")};const add=(e:RadarEvent)=>{localStorage.setItem("rl-events",JSON.stringify([e,...savedEvents()]));setList(l=>[e,...(l||[])]);setNow(Date.now());reset()};const term=q.trim().toLowerCase();const shown=(list||[]).filter(e=>(!cat||e.category===cat)&&(status==="todos"||(status==="pasados")===isPast(e,now))&&(!term||[e.title,e.description,e.location,e.organizer].some(x=>x.toLowerCase().includes(term)))).sort((a,b)=>status==="pasados"?b.start.localeCompare(a.start):a.start.localeCompare(b.start));const upcoming=(list||[]).filter(e=>!isPast(e,now)).length;return <main className="simple-page events-page"><div className="container"><div className="events-title"><div><span className="eyebrow"><Ticket/> Agenda de Chihuahua</span><h1>Eventos</h1><p className="lead">Conciertos, catas, expos y talleres organizados por los negocios de la ciudad.{list&&<> <b>{upcoming} próximos eventos.</b></>}</p></div><button className="btn event" aria-expanded={creating} onClick={()=>setCreating(c=>!c)}>{creating?<><X/> Cerrar formulario</>:<><CalendarPlus/> Crear evento</>}</button></div>{creating&&<EventForm onSave={add} onCancel={()=>setCreating(false)}/>}<EventFilters q={q} setQ={setQ} cat={cat} setCat={setCat} status={status} setStatus={setStatus}/>{list===null?<div className="event-grid">{[0,1,2].map(i=><div key={i} className="event-card skeleton"/>)}</div>:shown.length?<><p className="event-count">{shown.length} {shown.length===1?"evento":"eventos"}{(q||cat||status!=="proximos")&&<button onClick={reset}><RotateCcw/> Limpiar filtros</button>}</p><div className="event-grid">{shown.map(e=><EventCard key={e.id} e={e} past={isPast(e,now)} open={setOpen}/>)}</div></>:<Empty clear={reset}/>}</div>{open&&<EventModal e={open} past={isPast(open,now)} close={close}/>}</main>}
const periodInfo:Record<PromoPeriod,{label:string;help:string}>={mensual:{label:"Mensual",help:"Sale en la página de Promociones durante todo el mes."},semanal:{label:"Semanal",help:"Sale 7 días en «Promociones de la semana» del inicio y en la página de Promociones."}};
function PromoEditor({plan}:{plan:PlanId}){const[title,setTitle]=useState(""),[description,setDescription]=useState(""),[created,setCreated]=useState<Promotion|null>(null),[active,setActive]=useState(true),[period,setPeriod]=useState<PromoPeriod>("mensual");useEffect(()=>{setCreated(ownPromo())},[]);const weeklyLocked=!has(plan,"featured");return <div className="dashboard-grid"><div className="panel-card form-panel"><h3>Crear promoción</h3><p>La propuesta se guarda solo en este dispositivo.</p><p className="promo-quota">{plan==="basic"?`Plan Básico: ${created?1:0} de 1 promoción mensual activa este mes.`:"Plan Plus: promociones semanales y mensuales ilimitadas."}</p><fieldset className="type-filters promo-period"><legend>Tipo de promoción</legend><div className="filter-chips">{(["mensual","semanal"] as PromoPeriod[]).map(id=>{const locked=id==="semanal"&&weeklyLocked,on=period===id;return <label key={id} className={on?"on":""}><input type="radio" name="promo-period" checked={on} disabled={locked} onChange={()=>setPeriod(id)}/>{locked?<Lock/>:on&&<Check/>}{periodInfo[id].label}{locked&&" · Plus"}</label>})}</div><p>{periodInfo[period].help}{weeklyLocked&&" Las semanales requieren el plan Plus."}</p></fieldset><label>Título<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ej. Cena para dos"/></label><label>Descripción<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="Describe el beneficio"/></label><button className="btn primary" disabled={!title.trim()||(plan==="basic"&&!!created)} onClick={()=>{localStorage.setItem("rl-promos",title.trim());localStorage.setItem("rl-promo-period",weeklyLocked?"mensual":period);setCreated(ownPromo());setTitle("");setDescription("")}}><Plus/> Guardar propuesta</button>{created&&<span className="success"><Check/> Propuesta {created.period} guardada: {created.title}</span>}</div><div className="panel-card"><h3>{created?"Tu promoción":"Vista previa"}</h3>{active?<PromoCard p={created||promotions[0]}/>:<p>Oculta en este panel.</p>}<Toggle label={active?"Visible en este panel":"Oculta en este panel"} value={active} set={setActive}/></div></div>}
function Analytics({plan,setPlan}:{plan:PlanId;setPlan:(p:PlanId)=>void}){return <><div className="metrics"><Metric label="Visitas" value={plan==="featured"?"3,842":"1,190"} delta={plan==="featured"?"+16%":"+5%"} I={Compass}/><Metric label="Clics" value={plan==="featured"?"394":"118"} delta={plan==="featured"?"+11%":"+3%"} I={Phone}/>{plan==="featured"&&<Metric label="Promociones vistas" value="1,096" delta="+31%" I={Tag}/>}</div>{plan==="featured"?<article className="panel-card chart-card"><h3>Rendimiento mensual</h3><Chart/></article>:<Locked title="Estadísticas avanzadas" min="featured" gains={["Gráfica de rendimiento mensual","Vistas de tus promociones","Historial de contactos"]} setPlan={setPlan}/>}</>}
function Contacts(){return <div className="panel-card table-wrap"><h3>Contactos</h3><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Estado</th><th>Origen</th></tr></thead><tbody>{[["18 sep","WhatsApp","Nuevo","Perfil"],["17 sep","Cómo llegar","Visto","Promoción"],["16 sep","Sitio web","Visto","Explorador"]].map((r,i)=><tr key={i}>{r.map(x=><td key={x}>{x}</td>)}</tr>)}</tbody></table></div>}
